    }

    public Task<IReadOnlyList<TaskComment>> GetTaskCommentsAsync(string taskId, CancellationToken cancellationToken)
    {
        return Api.GetTaskCommentsAsync(taskId, cancellationToken);
    }

    public Task DeleteCommentAsync(string commentId, CancellationToken cancellationToken)
    {
        return Api.DeleteCommentAsync(commentId, cancellationToken);
    }

    private IJobTrackApi Api => _api ??= create();
}

