    private static readonly string[] TimestampPropertyNames = ["timestamp", "createdAt", "createdOn", "created", "updatedAt"];
    private static readonly string[] ContentPropertyNames = ["content", "body", "text"];
    private static readonly string[] NestedAuthorPropertyNames = ["displayName", "name", "email", "id"];
    private static readonly string[] FallbackAuthorPropertyNames = ["authorName", "createdBy", "createdByName", "userName", "userId"];

