internal static class UntrustedText
{
    // Bound API diagnostics to one small terminal page while preserving useful context.
    private const int MaxDiagnosticLength = 4096;

    public static string SingleLine(string value)
    {
        return EscapeControls(value);
    }

    public static string Diagnostic(string value)
    {
        var escaped = EscapeControls(value);
        if (escaped.Length <= MaxDiagnosticLength)
        {
            return escaped;
        }

        return string.Concat(escaped.AsSpan(0, MaxDiagnosticLength), "... [truncated]");
    }

    private static string EscapeControls(string value)
    {
        StringBuilder? builder = null;
        for (var index = 0; index < value.Length; index++)
        {
            var replacement = ControlReplacement(value[index]);
            if (replacement is null)
            {
                builder?.Append(value[index]);
                continue;
            }

            if (builder is null)
            {
                builder = new StringBuilder(value.Length + replacement.Length);
                builder.Append(value.AsSpan(0, index));
            }

            builder.Append(replacement);
        }

        return builder?.ToString() ?? value;
    }

    private static string? ControlReplacement(char value)
    {
        return value switch
        {
            '\b' => @"\b",
            '\f' => @"\f",
            '\n' => @"\n",
            '\r' => @"\r",
            '\t' => @"\t",
            '\u2028' => @"\u2028",
            '\u2029' => @"\u2029",
            _ when char.IsControl(value) => "\\u" + ((int)value).ToString("x4"),
            _ => null
        };
    }
}

internal static class JsonText
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        WriteIndented = true
    };

    public static string Pretty(string raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
        {
            return raw;
        }

        try
        {
            using var document = JsonDocument.Parse(raw);
            return JsonSerializer.Serialize(document.RootElement, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (JsonException)
        {
            return raw;
        }
    }

    public static string ToJson<T>(T value)
    {
