internal sealed class JobTrackApiException(
    string command,
    HttpStatusCode statusCode,
    string? reasonPhrase,
    string body,
    bool truncated = false,
    int maxBodyBytes = 0)
    : Exception(BuildMessage(command, statusCode, reasonPhrase, body, truncated, maxBodyBytes))
{
    private static string BuildMessage(
        string command,
        HttpStatusCode statusCode,
        string? reasonPhrase,
        string body,
        bool truncated,
        int maxBodyBytes)
    {
        var message = $"{command}: {(int)statusCode} {reasonPhrase}".TrimEnd();
        if (string.IsNullOrWhiteSpace(body) && !truncated)
        {
            return message;
        }

        var diagnostic = string.IsNullOrWhiteSpace(body)
            ? ""
            : UntrustedText.Diagnostic(body);
        if (truncated)
        {
            var truncation = $"[response body truncated at {maxBodyBytes} bytes]";
            diagnostic = diagnostic.Length == 0
                ? truncation
                : $"{diagnostic}{Environment.NewLine}{truncation}";
        }

