internal sealed class TaskCommentSettings : CommandSettings
{
    [CommandArgument(0, "<TASK_ID>")]
    [Description("Task id to comment on.")]
    public string TaskId { get; set; } = "";

    [CommandArgument(1, "[CONTENT]")]
    [Description("Comment content.")]
    public string? ContentArgument { get; set; }

    [CommandOption("-c|--content <CONTENT>")]
    [Description("Comment content.")]
    public string? ContentOption { get; set; }

    public string ResolvedContent => ContentOption ?? ContentArgument ?? "";

    public override ValidationResult Validate()
    {
        if (string.IsNullOrWhiteSpace(TaskId))
        {
            return ValidationResult.Error("Task id is required.");
        }

        if (string.IsNullOrWhiteSpace(ResolvedContent))
        {
            return ValidationResult.Error("Comment content is required. Pass it as an argument or with --content.");
        }

        if (!string.IsNullOrWhiteSpace(ContentArgument) && !string.IsNullOrWhiteSpace(ContentOption))
        {
            return ValidationResult.Error("Pass comment content either as an argument or with --content, not both.");
        }

        return ValidationResult.Success();
    }
}

