   116	internal sealed class JobTrackCommandApp(ICommandApp app) : ICommandApp
   117	{
   118	    public void Configure(Action<IConfigurator> configuration)
   119	    {
   120	        app.Configure(configuration);
   121	    }
   122	
   123	    public int Run(IEnumerable<string> args, CancellationToken cancellationToken)
   124	    {
   125	        return app.Run(RewriteArgs(args), cancellationToken);
   126	    }
   127	
   128	    public Task<int> RunAsync(IEnumerable<string> args, CancellationToken cancellationToken)
   129	    {
   130	        return app.RunAsync(RewriteArgs(args), cancellationToken);
   131	    }
   132	
   133	    private static string[] RewriteArgs(IEnumerable<string> args)
   134	    {
   135	        var rewritten = args.ToArray();
   136	        if (ShouldRewriteTaskCommentCreate(rewritten))
   137	        {
   138	            // Preserve the shorthand form `jt task comment <task-id> <content>`.
   139	            return rewritten.Take(2)
   140	                .Append("create")
   141	                .Concat(rewritten.Skip(2))
   142	                .ToArray();
   143	        }
   144	
   145	        return rewritten;
   146	    }
   147	
   148	    private static bool ShouldRewriteTaskCommentCreate(IReadOnlyList<string> args)
   149	    {
   150	        if (args.Count < 3 ||
   151	            !StringComparer.Ordinal.Equals(args[0], "task") ||
   152	            !StringComparer.Ordinal.Equals(args[1], "comment"))
   153	        {
   154	            return false;
   155	        }
   156	
   157	        return !IsHelpOption(args[2]) &&
   158	            !StringComparer.Ordinal.Equals(args[2], "create") &&
   159	            !StringComparer.Ordinal.Equals(args[2], "delete");
   160	    }
   161	
   162	    private static bool IsHelpOption(string value)
   163	    {
   164	        return StringComparer.Ordinal.Equals(value, "--help") ||
   165	            StringComparer.Ordinal.Equals(value, "-h") ||
   166	            StringComparer.Ordinal.Equals(value, "-?");
   167	    }
   168	}
