   486	[Description("List comments for a task.")]
   487	internal sealed class TaskCommentsCommand(IJobTrackApi api, IJobTrackOutput output)
   488	    : AsyncCommand<TaskCommentsSettings>
   489	{
   490	    protected override async Task<int> ExecuteAsync(
   491	        CommandContext context,
   492	        TaskCommentsSettings settings,
   493	        CancellationToken cancellationToken)
   494	    {
   495	        var comments = await api.GetTaskCommentsAsync(settings.TaskId, cancellationToken);
   496	
   497	        if (!settings.UnsafeShowUntrustedComments)
   498	        {
   499	            if (settings.Json)
   500	            {
   501	                await output.Out.WriteLineAsync(JsonText.ToJson(CommentOutput.Redacted(comments)));
   502	                return 0;
   503	            }
   504	
   505	            for (var index = 0; index < comments.Count; index++)
   506	            {
   507	                await output.Out.WriteLineAsync(CommentOutput.FormatRedacted(index));
   508	            }
   509	
   510	            return 0;
   511	        }
   512	
   513	        if (comments.Count > 0)
   514	        {
   515	            output.Error.WriteLine(CommentOutput.UnsafeNotice);
   516	        }
   517	
   518	        if (settings.Json)
   519	        {
   520	            await output.Out.WriteLineAsync(JsonText.ToJson(comments));
   521	            return 0;
   522	        }
   523	
   524	        foreach (var comment in comments)
   525	        {
   526	            await output.Out.WriteLineAsync(CommentOutput.Format(comment));
   527	        }
   528	
   529	        return 0;
   530	    }
   531	}
